def transform(grid):
    n = len(grid)
    tl = [row[:] for row in grid]
    tr = [[grid[n-1-j][i] for j in range(n)] for i in range(n)]
    bl = [[grid[j][n-1-i] for j in range(n)] for i in range(n)]
    br = [[grid[n-1-i][n-1-j] for j in range(n)] for i in range(n)]
    output = []
    for i in range(2*n):
        row = []
        for j in range(2*n):
            if i < n and j < n:
                row.append(tl[i][j])
            elif i < n and j >= n:
                row.append(tr[i][j-n])
            elif i >= n and j < n:
                row.append(bl[i-n][j])
            else:
                row.append(br[i-n][j-n])
        output.append(row)
    return output

